def claim(start,end,verdict,assessment,ids,kind='STATISTIC_OR_FINANCIAL_ASSUMPTION',occurrence=0):
 pat=lambda x:r'\s+'.join(re.escape(t) for t in x.split())
 ms=list(re.finditer(pat(start),S));assert len(ms)>occurrence,start;m=ms[occurrence];a=m.start()
 q=re.search(pat(end),S[m.end():]) if end else None
 assert not end or q,end
 b=m.end()+q.end() if q else m.end()
 claims.append(dict(claim_id=f'C{len(claims)+1:02}',start_char=a,end_char=b,original_quote=S[a:b],claim_type=kind,classification=verdict,assessment=assessment,source_ids=ids,wealth_definition='Net worth unless explicitly invested portfolio;definitions evaluated in assessment',population_and_age='Creator generalization unless source-limited;see linked source methodology',missing_assumptions='No universal first-crossing model;return,taxes,fees,asset mix and contribution timing conditional where relevant'))
