calc('One-year hypothetical8%growth','gain=P*r;ending=P*(1+r)',{'P':[200000,500000,1000000,2000000],'r':.08},{str(p):{'gain':p*.08,'ending':p*1.08} for p in [200000,500000,1000000,2000000]},'All initial amount invested and exposed to specified one-year return;nominal total return,not cash distributions or safe withdrawal. No contributions,tax/fees,inflation or guarantee.')
calc('No-contribution milestone times','t=ln(FV/P)/ln(1+r)',{'r':.08},{'100K_to250K_years':math.log(2.5)/math.log(1.08),'doubling_years':math.log(2)/math.log(1.08),'tenfold_years':math.log(10)/math.log(1.08),'1M_to2M':math.log(2)/math.log(1.08),'2M_to3M':math.log(1.5)/math.log(1.08),'3M_to4M':math.log(4/3)/math.log(1.08)},'Analyst conditional illustrations;no deposits/withdrawals,positiveconstant effective annual8%. No national wealth chronology follows.')
calc('Required monthly contributions for cited intervals','i=(1+r)^(1/12)-1;c=(FV-P*(1+i)^n)*i/((1+i)^n-1)',{'r':.08,'timing':'endmonth'}, {f'{p}_to{f}_{y}years':(f-p*1.08**y)*(1.08**(1/12)-1)/(1.08**y-1) for p,f,ys in [(0,100000,[6]),(100000,250000,[4,5,6]),(250000,500000,[5,7]),(500000,1000000,[5,10]),(200000,1000000,[5,10,14])] for y in ys},'Own feasible-contribution scenarios,not contributions supplied by narrator or observations. Contributions may be negative for longer-than-doubling windows;negative means possible withdrawal under perfect path,not recommended strategy.')
calc('35-year-old200K scenario and inflation sensitivity','FV=P*(1+r)^t;real=FV/(1+inflation)^t',{'P':200000,'t':14,'r':.08,'analyst_inflation':.03},{'FV_at49':200000*1.08**14,'real_at35_dollars':200000*1.08**14/1.03**14,'years_no_deposits_to1M':math.log(5)/math.log(1.08)},'Own3%inflation sensitivity,not forecast;consistent habits unspecified by creator. Monthly conventioneffective8%versusnominal8%/12 materially changes contributions.')
