calc('Housing20%scenario and rent transcription sensitivity','down=.2*price;rent_change=(1481/base-1)*100',{'prices':[429800,346526,285534],'rents':[1481,1251,1174,174]},{'downpayments':[.2*p for p in [429800,346526,285534]],'millennial_vs_boomer_corrected_rent_pct':(1481/1174-1)*100,'using_stored174_pct':(1481/174-1)*100},'Original analyst table comparability limitations in sourceledger. Only85960 primaryprice match established. Cannot identify spoken1174 without audio.')
calc('Income denominator conversion','annual_equivalent=weekly*52;comparison=40000/annual_equivalent',{'weekly':1196,'weeks':52,'gain':40000},{'annualized_weekly_median':1196*52,'gain_share':40000/(1196*52),'160K_to_household_median':160000/83730},'No annual employment duration assumed observed;workers vs households distinct. Annualizing weeklymedian is a scale comparison,not annualearningsmedian.')
calc('Cohort source internal arithmetic','difference_percent=(millennial/boomer-1)*100',{'median_rounded':[48000,63100],'wealth90th_rounded':[457000,373000]},{'median_pct':(48000/63100-1)*100,'wealth90th_pct':(457000/373000-1)*100},'Diagnostic of rounded source figures,not independent NLSY microdata replication;source text over30% conflicts with displayedmedianpair. Preserve uncertainty.')
